#include <bits/stdc++.h>
using namespace std;

vector<int> primes;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Generate primes up to 6000
    for (int p = 2; p < 6000; p++) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(p);
        }
    }

    // Function to factorize n into prime factors
    auto factor = [&](long long n) {
        unordered_map<long long, int> d;
        for (int p : primes) {
            long long p_ll = p;
            if (p_ll * p_ll > n) break;
            if (n % p_ll == 0) {
                int c = 0;
                while (n % p_ll == 0) {
                    n /= p_ll;
                    c++;
                }
                d[p_ll] = c;
            }
        }
        if (n > 1) {
            d[n] = 1;
        }
        return d;
    };

    // Function to generate all factors of n
    auto factors = [&](long long n) {
        auto d = factor(n);
        vector<long long> answer = {1};
        for (auto &p_c : d) {
            long long p = p_c.first;
            int c = p_c.second;
            vector<long long> a2;
            for (auto &x : answer) {
                long long p_pow = 1;
                for (int i = 0; i <= c; i++) {
                    a2.push_back(x * p_pow);
                    p_pow *= p;
                }
            }
            answer = a2;
        }
        return answer;
    };

    // Read input
    int n, m;
    cin >> n >> m;

    vector<long long> f_dict(n + 1);
    f_dict[0] = 0;
    if (n >= 1) f_dict[1] = 1;
    if (n >= 2) f_dict[2] = 2;

    for (int i = 3; i <= n; i++) {
        f_dict[i] = 2 * f_dict[i - 1];
        vector<long long> facs = factors(i);
        for (auto &x : facs) {
            if (x >= 2 && x <= i) {
                long long term = f_dict[i / x] - f_dict[(i - 1) / x];
                f_dict[i] += term;
            }
        }
        f_dict[i] %= m;
    }

    cout << f_dict[n] % m << "\n";

    return 0;
}
